function maximo(datos) {
  if (datos.length === 0) { return "Sin datos"; }
  let mayor = datos[0];
  for (let i = 1; i < datos.length; i = i + 1) {
    if (datos[i] > mayor) { mayor = datos[i]; }
  }
  return mayor;
}

function resumir(minutos, meta) {
  let total = 0;
  let cantidad = 0;
  for (let i = 0; i < minutos.length; i = i + 1) {
    total = total + minutos[i];
    if (minutos[i] >= meta) { cantidad = cantidad + 1; }
  }
  return [total, cantidad];
}

function fueraDeRango(datos, minimo, maximo) {
  let cantidad = 0;
  for (let i = 0; i < datos.length; i = i + 1) {
    if (datos[i] < minimo || datos[i] > maximo) { cantidad = cantidad + 1; }
  }
  return cantidad;
}
